/bin/bash -lc "python - <<'PY'
import cv2,numpy as np
A=np.load('source_pixels.npz')['rgb']
boxes=[(50,125,25,110),(95,140,25,110),(135,165,25,110),(168,205,25,110)]
for fi in range(0,31):
 vals=[]
 for bi,(x0,x1,y0,y1) in enumerate(boxes):
  g=cv2.cvtColor(A[fi,y0:y1,x0:x1],cv2.COLOR_RGB2GRAY);e=cv2.Canny(g,25,70)
  l=cv2.HoughLinesP(e,1,np.pi/720,threshold=14,minLineLength=25,maxLineGap=3)
  q=[]
  if l is not None:
   for x2,y2,x3,y3 in l[:,0]:
    dx=x3-x2;dy=y3-y2; ln=np.hypot(dx,dy);ang=np.degrees(np.arctan2(dy,dx));
    if ang>90:ang-=180
    if ang<-90:ang+=180
    if abs(ang)>8:q.append((ln,ang))
  if q:
   q.sort(reverse=True); vals.append(round(q[0][1],1))
  else: vals.append(None)
 print(fi+1,vals)
PY"
